(function(){
  const LIBRARY_URL='https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.14';
  const WASM_URL=`${LIBRARY_URL}/wasm`;
  const MODEL_URL='https://storage.googleapis.com/mediapipe-models/face_landmarker/face_landmarker/float16/1/face_landmarker.task';
  const LIP_OUTER=[61,185,40,39,37,0,267,269,270,409,291,375,321,405,314,17,84,181,91,146];
  const LIP_INNER=[78,191,80,81,82,13,312,311,310,415,308,324,318,402,317,14,87,178,88,95];
  const RIGHT_LID=[33,246,161,160,159,158,157,173,133],LEFT_LID=[263,466,388,387,386,385,384,398,362];
  const RIGHT_BROW_TOP=[70,63,105,66,107],RIGHT_BROW_BOTTOM=[55,65,52,53,46];
  const LEFT_BROW_TOP=[336,296,334,293,300],LEFT_BROW_BOTTOM=[285,295,282,283,276];
  const GLOSS_POINTS=[14,17,84,314];
  class ShadeTryOn{
    constructor({video,canvas,stage,onStatus}){this.video=video;this.canvas=canvas;this.stage=stage;this.ctx=canvas.getContext('2d');this.onStatus=onStatus||(()=>{});this.paintLayer=document.createElement('canvas');this.paintCtx=this.paintLayer.getContext('2d');this.landmarker=null;this.stream=null;this.running=false;this.lastVideoTime=-1;this.settings={lips:{on:true,hex:'#9B435C',finish:'matte',intensity:.70},brows:{on:false,hex:'#4B302A',finish:'matte',intensity:.34},eyes:{on:false,hex:'#8A5D70',finish:'matte',intensity:.45}};}
    async loadModel(){if(this.landmarker)return true;this.onStatus('loading','Loading face tracking…');try{const vision=await import(LIBRARY_URL);const files=await vision.FilesetResolver.forVisionTasks(WASM_URL);try{this.landmarker=await vision.FaceLandmarker.createFromOptions(files,{baseOptions:{modelAssetPath:MODEL_URL,delegate:'GPU'},runningMode:'VIDEO',numFaces:1});}catch{this.landmarker=await vision.FaceLandmarker.createFromOptions(files,{baseOptions:{modelAssetPath:MODEL_URL,delegate:'CPU'},runningMode:'VIDEO',numFaces:1});}return true;}catch(error){this.onStatus('failed','Face tracking could not load. Check your connection and try again.');return false;}}
    async start(){this.stop();if(!(await this.loadModel()))return false;if(!navigator.mediaDevices?.getUserMedia){this.onStatus('failed','This browser cannot open a camera.');return false;}try{this.stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:960},height:{ideal:720}},audio:false});this.video.srcObject=this.stream;await this.video.play();const w=this.video.videoWidth||960,h=this.video.videoHeight||720;this.canvas.width=w;this.canvas.height=h;this.paintLayer.width=w;this.paintLayer.height=h;this.running=true;this.lastVideoTime=-1;this.onStatus('live','Tracking your lips, brows and eyelids');requestAnimationFrame(()=>this.loop());return true;}catch(error){this.onStatus('failed',error?.name==='NotAllowedError'?'Camera permission was not granted.':'Front camera unavailable.');return false;}}
    stop(){this.running=false;if(this.stream){this.stream.getTracks().forEach(track=>track.stop());this.stream=null;}this.video.srcObject=null;this.ctx.clearRect(0,0,this.canvas.width,this.canvas.height);this.stage.classList.add('searching');}
    set(region,patch){Object.assign(this.settings[region],patch);}
    loop(){if(!this.running)return;const now=performance.now();if(this.video.readyState>=2&&this.video.currentTime!==this.lastVideoTime){this.lastVideoTime=this.video.currentTime;let result=null;try{result=this.landmarker.detectForVideo(this.video,now);}catch{}this.draw(result);}requestAnimationFrame(()=>this.loop());}
    draw(result){const w=this.canvas.width,h=this.canvas.height;this.ctx.clearRect(0,0,w,h);const landmarks=result?.faceLandmarks?.[0];if(!landmarks){this.stage.classList.add('searching');return;}this.stage.classList.remove('searching');if(this.settings.eyes.on)this.paintEyes(landmarks,w,h);if(this.settings.brows.on)this.paintBrows(landmarks,w,h);if(this.settings.lips.on)this.paintLips(landmarks,w,h);}
    points(indices,lm,w,h){return indices.map(index=>({x:lm[index].x*w,y:lm[index].y*h}));}
    smoothPath(ctx,points){if(!points.length)return;ctx.beginPath();ctx.moveTo(points[0].x,points[0].y);for(let i=0;i<points.length;i++){const here=points[i],next=points[(i+1)%points.length];ctx.quadraticCurveTo(here.x,here.y,(here.x+next.x)/2,(here.y+next.y)/2);}ctx.closePath();}
    resetLayer(w,h,blur){const lc=this.paintCtx;lc.setTransform(1,0,0,1,0,0);lc.clearRect(0,0,w,h);lc.globalCompositeOperation='source-over';lc.globalAlpha=1;lc.filter=blur?`blur(${blur}px)`:'none';return lc;}
    composite(alpha,extra=.22){this.ctx.save();this.ctx.globalCompositeOperation='multiply';this.ctx.globalAlpha=Math.min(1,alpha);this.ctx.drawImage(this.paintLayer,0,0);if(extra){this.ctx.globalCompositeOperation='source-over';this.ctx.globalAlpha=Math.min(.45,alpha*extra);this.ctx.drawImage(this.paintLayer,0,0);}this.ctx.restore();}
    paintLips(lm,w,h){const cfg=this.settings.lips,lc=this.resetLayer(w,h,2.2);lc.fillStyle=cfg.hex;this.smoothPath(lc,this.points(LIP_OUTER,lm,w,h));lc.fill();lc.globalCompositeOperation='destination-out';lc.filter='blur(1px)';this.smoothPath(lc,this.points(LIP_INNER,lm,w,h));lc.fill();lc.globalCompositeOperation='source-over';lc.filter='none';const finish=cfg.finish==='sheer'?.55:cfg.finish==='glossy'?.84:1;this.composite(cfg.intensity*finish,cfg.finish==='sheer'?.1:.28);if(cfg.finish==='glossy')this.paintGloss(lm,w,h,cfg.intensity);}
    paintGloss(lm,w,h,intensity){const pts=this.points(GLOSS_POINTS,lm,w,h),cx=pts.reduce((s,p)=>s+p.x,0)/pts.length,cy=pts.reduce((s,p)=>s+p.y,0)/pts.length,span=Math.hypot((lm[61].x-lm[291].x)*w,(lm[61].y-lm[291].y)*h);this.ctx.save();this.ctx.globalCompositeOperation='screen';this.ctx.globalAlpha=Math.min(.5,intensity*.45);this.ctx.filter='blur(3px)';this.ctx.fillStyle='#fff';this.ctx.beginPath();this.ctx.ellipse(cx,cy+span*.006,span*.15,span*.045,0,0,Math.PI*2);this.ctx.fill();this.ctx.restore();}
    eyeShape(lm,lid,brow,w,h){const lids=this.points(lid,lm,w,h),inner=lids[0],outer=lids[lids.length-1];const lifted=this.points(brow,lm,w,h).map(p=>{const ref=Math.abs(p.x-inner.x)<Math.abs(p.x-outer.x)?inner:outer;return{x:p.x+(ref.x-p.x)*.42,y:p.y+(ref.y-p.y)*.42};});return lids.concat(lifted.reverse());}
    paintEyes(lm,w,h){const cfg=this.settings.eyes,span=Math.hypot((lm[33].x-lm[263].x)*w,(lm[33].y-lm[263].y)*h),lc=this.resetLayer(w,h,Math.max(3,span*.026));lc.fillStyle=cfg.hex;[[RIGHT_LID,RIGHT_BROW_BOTTOM],[LEFT_LID,LEFT_BROW_BOTTOM]].forEach(([lid,brow])=>{this.smoothPath(lc,this.eyeShape(lm,lid,brow,w,h));lc.fill();});lc.filter='none';this.composite(cfg.intensity,cfg.finish==='shimmer'?.35:.12);if(cfg.finish==='shimmer'){this.ctx.save();this.ctx.globalCompositeOperation='screen';this.ctx.globalAlpha=cfg.intensity*.22;this.ctx.drawImage(this.paintLayer,0,0);this.ctx.restore();}}
    browShape(top,bottom,lm,w,h){return this.points(top,lm,w,h).concat(this.points(bottom,lm,w,h).reverse());}
    paintBrows(lm,w,h){const cfg=this.settings.brows,lc=this.resetLayer(w,h,1.6);lc.fillStyle=cfg.hex;[[RIGHT_BROW_TOP,RIGHT_BROW_BOTTOM],[LEFT_BROW_TOP,LEFT_BROW_BOTTOM]].forEach(([top,bottom])=>{this.smoothPath(lc,this.browShape(top,bottom,lm,w,h));lc.fill();});lc.filter='none';this.composite(cfg.intensity,.08);}
  }
  window.ShadeTryOn=ShadeTryOn;
})();
